209	    param(
210	        [Parameter(Mandatory)][string]$ScriptPath,
211	        [string[]]$Arguments = @(),
212	        [string]$StandardInput = ''
213	    )
214	
215	    $pluginRootFull = Resolve-FullPath $script:McpPluginInvocation.PluginRoot
216	    $workspaceFull = Resolve-OptionalDirectory $script:McpPluginInvocation.WorkspacePath
217	    $cacheOverrideFull = if ($script:McpPluginInvocation.CacheRoot) {
218	        Resolve-OptionalDirectory $script:McpPluginInvocation.CacheRoot
219	    } elseif (-not $script:McpPluginWorkspacePathExplicit -and $env:MCP_CACHE_DIR_OVERRIDE) {
220	        Resolve-OptionalDirectory $env:MCP_CACHE_DIR_OVERRIDE
221	    } else {
222	        $null
223	    }
224	    $startInfo = [System.Diagnostics.ProcessStartInfo]::new()
225	    $startInfo.FileName = (Get-Command pwsh -ErrorAction Stop).Source
226	    $startInfo.WorkingDirectory = $workspaceFull
227	    $startInfo.UseShellExecute = $false
228	    $startInfo.RedirectStandardInput = $true
229	    $startInfo.RedirectStandardOutput = $true
230	    $startInfo.RedirectStandardError = $true
231	    $startInfo.ArgumentList.Add('-NoLogo')
232	    $startInfo.ArgumentList.Add('-NoProfile')
233	    $startInfo.ArgumentList.Add('-NonInteractive')
234	    $startInfo.ArgumentList.Add('-File')
235	    $startInfo.ArgumentList.Add((Resolve-FullPath $ScriptPath))
236	    foreach ($argument in $Arguments) {
237	        $startInfo.ArgumentList.Add($argument)
238	    }
239	    $startInfo.Environment['MCP_PLUGIN_ROOT'] = $pluginRootFull
240	    $startInfo.Environment['CLAUDE_PLUGIN_ROOT'] = $pluginRootFull
241	    $resolvedHost = Resolve-McpPluginHostName -Root $pluginRootFull
242	    $hostDefaults = if ($resolvedHost) { Get-McpPluginHostDefaults -HostName $resolvedHost } else { $null }
243	    if ($hostDefaults) {
244	        $startInfo.Environment['MCP_PLUGIN_HOST'] = [string]$hostDefaults.Host
245	        $startInfo.Environment['PLUGIN_AGENT_DEFAULT'] = [string]$hostDefaults.Agent
246	        $startInfo.Environment['PLUGIN_MODEL_DEFAULT'] = [string]$hostDefaults.Model
247	        $startInfo.Environment['PLUGIN_TAG'] = [string]$hostDefaults.Tag
248	        $startInfo.Environment['MCP_AGENT_NAME'] = [string]$hostDefaults.Agent
249	        $startInfo.Environment['MCP_AGENT_ID'] = [string]$hostDefaults.Agent
250	        $startInfo.Environment['MCP_SESSION_AGENT'] = [string]$hostDefaults.Agent
251	        $startInfo.Environment['MCP_SESSION_MODEL'] = [string]$hostDefaults.Model
252	        $startInfo.Environment['MCP_SESSION_TITLE'] = "$($hostDefaults.Agent) plugin session"
253	        $startInfo.Environment['CT2R_SOURCE_TYPE'] = [string]$hostDefaults.Agent
254	        $startInfo.Environment['CT2R_MODEL'] = [string]$hostDefaults.Model
255	        $startInfo.Environment['CT2R_TITLE'] = "$($hostDefaults.Agent) turn"
256	        $startInfo.Environment['CT2R_TAGS'] = [string]$hostDefaults.Tag
257	        if ($hostDefaults.Host -ne 'codex') {
258	            foreach ($codexName in @('CODEX_PLUGIN_ROOT', 'CODEX_WORKSPACE_PATH', 'CODEX_PROJECT_DIR', 'CODEX_CWD')) {
259	                [void]$startInfo.Environment.Remove($codexName)
260	            }
261	        }
262	    }
263	    [void]$startInfo.Environment.Remove('MCP_CACHE_DIR_OVERRIDE')
264	    [void]$startInfo.Environment.Remove('PLUGIN_ROOT_OVERRIDE')
265	    if ($cacheOverrideFull) {
266	        $startInfo.Environment['MCP_CACHE_DIR_OVERRIDE'] = $cacheOverrideFull
267	    }
268	    $startInfo.Environment['MCP_WORKSPACE_PATH'] = $workspaceFull
269	    $startInfo.Environment['MCPSERVER_WORKSPACE_PATH'] = $workspaceFull
270	    $startInfo.Environment['MCP_WORKSPACE_START_DIR'] = $workspaceFull
271	    $startInfo.Environment['CLAUDE_PROJECT_DIR'] = $workspaceFull
272	
273	    $process = [System.Diagnostics.Process]::new()
274	    $process.StartInfo = $startInfo
275	    [void]$process.Start()
276	
277	    if ($StandardInput.Length -gt 0) {
278	        $process.StandardInput.Write($StandardInput)
279	    }
280	    $process.StandardInput.Close()
281	
282	    $stdoutTask = $process.StandardOutput.ReadToEndAsync()
283	    $stderrTask = $process.StandardError.ReadToEndAsync()
284	    $boundedTimeout = [Math]::Max(1, $script:McpPluginInvocation.TimeoutSeconds)
285	    if (-not $process.WaitForExit($boundedTimeout * 1000)) {
286	        try {
287	            $process.Kill($true)
288	        } catch {
289	        }
290	        try { [void]$process.WaitForExit(2000) } catch { }
291	        # TR-MCP-TRIAGEPLUGIN-004 / BUG-TRIAGE-120: never throw an unclassified
292	        # timeout. Session-log callers treat command_timeout as retryable
293	        # degraded/queued and keep failsafe on disk. The envelope is a native
294	        # object serialized through the YAML serializer, never handwritten text.
295	        $envelope = (ConvertTo-McpPluginYaml -InputObject (New-McpPluginTimeoutEnvelope -TimeoutSeconds $boundedTimeout)).TrimEnd("`r", "`n")
296	        Write-Output $envelope
297	        [Console]::Error.WriteLine($envelope)
298	        return
299	    }
300	
301	    $stdout = $stdoutTask.Result
302	    $stderr = $stderrTask.Result
303	
304	    if ($stderr.Length -gt 0) {
305	        [Console]::Error.Write($stderr)
306	    }
307	
308	    if ($stdout.Length -gt 0) {
309	        Write-Output ($stdout.TrimEnd("`r", "`n"))
310	    }
311	
312	    if ($process.ExitCode -ne 0) {
313	        $msg = "Plugin command failed with exit code $($process.ExitCode)."
314	        if ($stdout) { $msg += "`n" + $stdout }
315	        throw $msg
316	    }
317	}
318	
319	$pluginRootFull = Resolve-FullPath $script:McpPluginInvocation.PluginRoot
320	
321	switch ($script:McpPluginInvocation.Command) {
322	    'Status' {
323	        Invoke-PluginPowerShellScript -ScriptPath (Resolve-PluginPowerShellScript -Root $pluginRootFull -Name 'mcp-status.ps1')
324	    }
325	    'Invoke' {
326	        if (-not $script:McpPluginInvocation.Method) {
327	            throw '-Method is required when -Command Invoke is used.'
328	        }
329	
330	        $paramsText = if ($script:McpPluginParamsObjectBound) {
331	            $script:McpPluginInvocation.Params
332	        } else {
333	            Read-OptionalText -Inline $script:McpPluginInvocation.Params -HasInline:$($PSBoundParameters.ContainsKey('Params')) -Path $script:McpPluginInvocation.ParamsPath -AllowRedirectedInput
334	        }
335	        # Params travel in a file, never on the child command line (32,767-character limit on Windows).
336	        $paramsTransfer = New-McpReplParamsTransfer -ParamsText ($paramsText ?? '')
337	        try {
338	            Invoke-PluginPowerShellScript -ScriptPath (Resolve-PluginPowerShellScript -Root $pluginRootFull -Name 'repl-invoke.ps1') -Arguments (@('-Method', $script:McpPluginInvocation.Method) + @($paramsTransfer.Arguments))
339	        }
340	        finally {
341	            Remove-McpReplParamsTransfer -Transfer $paramsTransfer
342	        }
343	    }
344	    'CompleteTurn' {
345	        $responseText = Read-OptionalText -Inline $script:McpPluginInvocation.Response -HasInline:$($PSBoundParameters.ContainsKey('Response')) -Path $script:McpPluginInvocation.ResponsePath -AllowRedirectedInput
346	        if (-not $responseText) {
347	            $responseText = 'Turn completed.'
348	        }
349	
350	        Invoke-PluginPowerShellScript -ScriptPath (Resolve-PluginPowerShellScript -Root $pluginRootFull -Name 'final-response.ps1') -StandardInput $responseText
351	    }
352	}
