$status = & $wrapper -Command Status -WorkspacePath $ws -PluginRoot $plugin 2>&1
$text = ($status | Out-String)
$text = [regex]::Replace($text, '(?i)(api[_-]?key["'':\s=]+)[A-Za-z0-9_\-]{20,}', '$1<redacted>')
Write-Output $text

$turnFile = Join-Path $ws '.mcpServer/claude/current-turn.yaml'
if (Test-Path -LiteralPath $turnFile) {
    Write-Output "---- current-turn.yaml"
    Get-Content -LiteralPath $turnFile | Where-Object { $_ -notmatch '(?i)api[_-]?key|token:|secret|password' } | Select-Object -First 40 | ForEach-Object { Write-Output $_ }
}

. (Join-Path $plugin 'lib/yaml-object-mutation.ps1')
Import-McpYamlSerializer
$bom = [string][char]0xFEFF
function Get-Prop {
    param($Obj, [string]$Name)
    if ($null -eq $Obj) { return $null }
    if ($Obj -is [System.Collections.IDictionary]) { if ($Obj.Contains($Name)) { return $Obj[$Name] } else { return $null } }
    $p = $Obj.PSObject.Properties[$Name]
    if ($p) { return $p.Value }
    return $null
}
foreach ($scope in @('Global', 'Workspace')) {
    $paramsObject = [ordered]@{ scope = $scope }
    $raw = & $wrapper -Command Invoke -Method 'workflow.memory.list' -ParamsObject $paramsObject -WorkspacePath $ws -PluginRoot $plugin 2>$null
    $mtext = ($raw | Out-String).Replace($bom, '')
    $doc = $null
    try { $doc = ConvertFrom-Yaml -Yaml $mtext -ErrorAction Stop } catch { $doc = $null }
    if ($null -eq $doc) {
        Write-Output ("SCOPE {0}: UNPARSEABLE response length={1}; not rendered." -f $scope, $mtext.Length)
        continue
    }
    $payload = Get-Prop $doc 'payload'
    $result = Get-Prop $payload 'result'
    if ($null -eq $result) { $result = Get-Prop $doc 'result' }
    $items = Get-Prop $result 'items'
    if ($null -eq $items) { $items = Get-Prop $result 'memories' }
    if ($null -eq $items) {
        $keys = if ($result -is [System.Collections.IDictionary]) { $result.Keys -join ',' } else { '' }
        Write-Output ("SCOPE {0}: no items collection (type={1}; resultKeys={2})" -f $scope, (Get-Prop $doc 'type'), $keys)
        continue
    }
    $all = @($items)
    $filtered = @($all | Where-Object { [string](Get-Prop $_ 'id') -ne 'PRIVATE-MEMORY-REFERENCE-007' })
    Write-Output ("SCOPE {0}: returned={1} excludedProcess007={2} rendered={3} totalCount={4} hasMore={5}" -f $scope, $all.Count, ($all.Count - $filtered.Count), $filtered.Count, (Get-Prop $result 'totalCount'), (Get-Prop $result 'hasMore'))
    foreach ($m in ($filtered | Sort-Object { [string](Get-Prop $_ 'id') })) {
        Write-Output ("==== {0} [{1}] scope={2}" -f (Get-Prop $m 'id'), (Get-Prop $m 'category'), (Get-Prop $m 'scope'))
        Write-Output ([string](Get-Prop $m 'text'))
    }
}

